import re

_HEADER = re.compile(r'bytes=(?:([0-9]+)-([0-9]+)?|-([0-9]+))')


def bounds(header, length):
    """Parse a single range header against a resource of `length` bytes.

    Returns the inclusive (start, end) byte positions, or None when the
    header is not exactly one of `bytes=D-D`, `bytes=D-`, `bytes=-D` with
    ASCII digits, or the range is unsatisfiable.
    """
    if not isinstance(header, str):
        return None
    match = _HEADER.fullmatch(header)
    if match is None:
        return None
    length = int(length)
    if length == 0:
        return None
    if match.group(3) is not None:
        suffix = int(match.group(3))
        if suffix == 0:
            return None
        start = length - suffix
        if start < 0:
            start = 0
        return start, length - 1
    start = int(match.group(1))
    if start >= length:
        return None
    end = int(match.group(2)) if match.group(2) is not None else length - 1
    if end > length - 1:
        end = length - 1
    if end < start:
        return None
    return start, end

