from .ranges import bounds


def serve(data, range_header=None):
    total = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(total)}, data
    result = bounds(range_header, total)
    if result is None:
        return 416, {'Content-Length': '0',
                     'Content-Range': f'bytes */{total}'}, b''
    start, end = result
    body = data[start:end + 1]
    return 206, {'Content-Length': str(len(body)),
                 'Content-Range': f'bytes {start}-{end}/{total}'}, body
